// Get Conversation from Transcript code as described before
const downloadedData = $input.item.json;
const callIdFromPrevious = $('Prepare S3 Download (Transcript)').item.json.callid;
let conversationArray = [];
if (Array.isArray(downloadedData)) { conversationArray = downloadedData; }
else if (downloadedData && downloadedData.conversations && Array.isArray(downloadedData.conversations)) { conversationArray = downloadedData.conversations; }
else if (downloadedData && downloadedData.conversation && Array.isArray(downloadedData.conversation)) { conversationArray = downloadedData.conversation; }
else { console.warn(`Conversation array not found for callid: ${callIdFromPrevious}`); }
return { json: { callid: callIdFromPrevious, conversation: conversationArray, ...$('Get Calls for LLM Analysis').item.json } };

// Prompt oluştur
// Conversation verisini al
let conversation;
let callid_from_input = 'unknown';
try {
  const convNodeOutput = $input.first().json; // Process Conversation'dan gelen veri
  conversation = convNodeOutput.conversation || [];
  callid_from_input = convNodeOutput.callid || 'unknown';
  if (!Array.isArray(conversation)) {
    console.log('Uyarı: conversation bir array değil');
    conversation = [];
  }
} catch (error) {
  console.log('Hata (Create Analysis Prompt - conversation):', error.message);
  conversation = [];
}

// Prompt oluştur
const promptsystem = `
You are a call center conversation analyzer.

Below is a JSON array called \`conversation\`, where each item represents a speech block with the following structure:
{
  "speaker": "speaker_0" or "speaker_1" or "unknown",
  "text": "spoken words",
  "start": float (start time in seconds),
  "end": float (end time in seconds),
  "conversation_index": integer (order of conversation)
}

Your task is to analyze this conversation based on the following criteria. Respond with true, false, or "unknown" for boolean questions. For the sale value scale, use an integer from 1 to 5 if a sale occurred, otherwise use 0 or null.

Instructions:
1.  Determine which speaker is the **call center agent** and which is the **customer**.
2.  Analyze the **customer's emotional tone** (e.g., calm, angry, excited, confused, etc.).
3.  Assess overall **conversation sentiment** (positive, negative, neutral).
4.  Identify the **main topic** (e.g., complaint, sales, technical issue, billing).
5.  Extract the **most significant term/keyword** (e.g., 'approved', 'canceled', 'offer', 'refund').
6.  Classify the **general experience** (acceptable, unacceptable, neutral).
7.  Summarize **customer's experience in one word** (e.g., frustrating, smooth, excellent).
8.  Was an **email address asked for or provided**?
9.  Did any **positive comments from the customer lead to or reinforce a sale/commitment**?
10. Did any **negative comments from the customer prevent or hinder a sale/commitment**?
11. Was there any **price negotiation**?
12. Was the **customer addressed politely** (e.g., using their name, polite phrases)?
13. Did the conversation seem **lighthearted or fun** at any point?
14. Were the **advantages of the services/products clearly mentioned** to the customer?
15. Were **competing platforms or services (other than Google's own, if applicable) mentioned**?
16. Was a **sale or commitment made** by the customer? (successful, unsuccessful, not_applicable)
17. If a sale was made, **rate its significance or value on a scale of 1 (low) to 5 (high)**.
18. Was the customer asked if they **knew any of the people who left reviews/comments** (if reviews were discussed)?
19. Were **advantages of a premium/high-level profile or service tier mentioned**?

If the conversation array is empty or analysis cannot be performed, return a valid JSON object with all fields set to "unknown" or null as appropriate, and include an "llm_error_message" field with a short explanation (e.g., "Insufficient data for analysis" or "Empty conversation transcript").

Return the result in only this JSON format (ensure valid JSON, no markdown, boolean values as true/false not strings "true"/"false"):

{
  "sentiment": "<positive|negative|neutral|unknown>",
  "topic": "<conversation_topic|unknown>",
  "significant_term": "<most_relevant_keyword|unknown>",
  "general_value": "<acceptable|unacceptable|neutral|unknown>",
  "general_experience": "<one_word_summary|unknown>",
  "email_inquired": "<true|false|unknown>",
  "positive_comment_passed_sale": "<true|false|unknown>",
  "negative_comment_passed_sale": "<true|false|unknown>",
  "price_negotiated": "<true|false|unknown>",
  "customer_addressed_politely": "<true|false|unknown>",
  "conversation_fun": "<true|false|unknown>",
  "service_advantages_mentioned": "<true|false|unknown>",
  "other_platforms_mentioned": "<true|false|unknown>",
  "sale_outcome": "<successful|unsuccessful|not_applicable|unknown>",
  "sale_value_scale": "<integer_0_to_5|null>",
  "asked_if_commenters_known": "<true|false|unknown>",
  "high_profile_advantages_mentioned": "<true|false|unknown>",
  "llm_error_message": "<error_message_if_any_or_null>"
}
`;

const promptuser = `

Here is the JSON transcript to analyze:

${JSON.stringify(conversation, null, 2)}
`;

// Sonucu döndür
return [{ json: { ...$input.item.json, promptsys: promptsystem, promtuser : promptuser } }];

const llmInputItem = $input.first();
let output = {};
let llmError = null;
let reasoningText = null;

const modelName = "Claude opus 3";

// JSON uyumlu hale getirme (llm_error_message ve reasoning için)
const sanitizeText = (text) => {
  if (!text || typeof text !== 'string') return text;
  return text
    .replace(/["']/g, '-')     // Tırnakları tireyle değiştir
    .replace(/\n/g, ' ')       // Satır sonlarını boşluk yap
    .replace(/\r/g, ' ')
    .replace(/\\/g, '-');      // backslash'ı da kaldır
};

// Normalizasyon
const normalizeValue = (val) => {
  if (val === undefined || val === null || val === 'unknown') return null;
  if (typeof val === 'number' && isNaN(val)) return null;
  return val;
};

// Beklenen alanlar
const defaultFields = {
  sentiment: null,
  topic: null,
  significant_term: null,
  general_value: null,
  general_experience: null,
  email_inquired: null,
  positive_comment_passed_sale: null,
  negative_comment_passed_sale: null,
  price_negotiated: null,
  customer_addressed_politely: null,
  conversation_fun: null,
  service_advantages_mentioned: null,
  other_platforms_mentioned: null,
  sale_outcome: null,
  sale_value_scale: null,
  asked_if_commenters_known: null,
  high_profile_advantages_mentioned: null,
  llm_error_message: null
};

// Call ID çekimi
let callid = 'unknown';
try {
  callid = normalizeValue(
    llmInputItem.json.callid ||
    $('Create Analysis Prompt').first().json.callid ||
    $('Get Conversation from Transcript').first().json.callid
  ) || 'unknown';
} catch (err) {
  console.log('callid alınamadı:', err.message);
}

// Ana işleme
if (llmInputItem.json.error) {
  llmError = llmInputItem.json.error.message || 'LLM bilinmeyen hata';
  output = {
    ...defaultFields,
    llm_error_message: sanitizeText(llmError)
  };
} else if (llmInputItem.json && llmInputItem.json.text) {
  let responseText = llmInputItem.json.text.trim();

  // Kod bloğu varsa temizle
  if (responseText.startsWith('```')) {
    responseText = responseText.replace(/^```json|^```/, '').replace(/```$/, '').trim();
  }

  // Gömülü JSON'u yakala
  const jsonStartIndex = responseText.indexOf('{');
  const jsonEndIndex = responseText.lastIndexOf('}');

  if (jsonStartIndex !== -1 && jsonEndIndex !== -1 && jsonEndIndex > jsonStartIndex) {
    let jsonString = responseText.slice(jsonStartIndex, jsonEndIndex + 1);

    // Reasoning ayıklama
    const reasoningIndex = responseText.indexOf('Reasoning:');
    if (reasoningIndex !== -1) {
      reasoningText = sanitizeText(responseText.slice(reasoningIndex + 10).trim());
    }

    try {
      const parsed = JSON.parse(jsonString);

      for (const key in defaultFields) {
        output[key] = normalizeValue(parsed[key]);
      }

    } catch (err) {
      llmError = 'LLM yanıtı JSON parse hatası: ' + err.message;
      output = {
        ...defaultFields,
        raw_text: responseText,
        llm_error_message: sanitizeText(llmError)
      };
    }
  } else {
    llmError = 'JSON yapısı bulunamadı.';
    output = {
      ...defaultFields,
      raw_text: responseText,
      llm_error_message: sanitizeText(llmError)
    };
  }
} else {
  llmError = 'LLM yanıtı boş veya text alanı yok.';
  output = {
    ...defaultFields,
    llm_error_message: sanitizeText(llmError)
  };
}

// LLM hatası yoksa "no_error" yaz
output.llm_error_message = output.llm_error_message === null ? 'no_error' : output.llm_error_message;

// Reasoning varsa ekle
if (reasoningText) {
  output.reasoning_text = reasoningText;
}

// Final JSON çıktı
return [{
  json: {
    ...output,
    callid: callid,
    model: modelName
  }
}];

