UPDATE public.pipe_response SET llm_error = '{{ $('Format LLM Response').item.json.llm_error_message.substring(0,250) }}', llm_processed = TRUE, analysis_s3_url = null, 
   updated_at = '{{ $now }}'
   WHERE callid = '{{ $('Format LLM Response').item.json.callid }}' ON CONFLICT (callid) DO UPDATE SET llm_error = EXCLUDED.llm_error, llm_processed = EXCLUDED.llm_processed, analysis_s3_url = EXCLUDED.analysis_s3_url,updated_at = Exclude.updated_at;

